{name="Expresiones con animales",t="x",w={{"ser un gallina","être une poule mouillée"},{"estar como una vaca","être très gros (fam.)"},{"tener memoria de pez","avoir une mémoire de poisson rouge"},{"ser un lince","être très perspicace"},{"aquí hay gato encerrado","il y a anguille sous roche"},{"ponerse como un tomate","rougir comme une tomate"},{"cuatro gatos","quatre pelés et un tondu"},{"estar como una sardina en lata","être serrés comme des sardines"},{"ser un pez gordo","être un gros bonnet"},{"llevarse como el perro y el gato","s'entendre comme chien et chat"},{"tener vista de águila","avoir des yeux de lynx"},{"ser un zorro","être un fin renard"},{"lágrimas de cocodrilo","larmes de crocodile"},{"tener pájaros en la cabeza","avoir la tête dans les nuages"},{"estar hecho un toro","être fort comme un bœuf"},{"ser más terco que una mula","être têtu comme une mule"},{"a paso de tortuga","à pas de tortue"},{"el patito feo","le vilain petit canard"},{"coger el toro por los cuernos","prendre le taureau par les cornes"},{"de perros (tiempo)","un temps de chien"},{"ser un ratón de biblioteca","être un rat de bibliothèque"},{"hacer el ganso","faire l'idiot"},{"estar como una foca","être énorme (fam.)"},{"como pulpo en un garaje","comme un poisson hors de l'eau"},{"ser una víbora","être une vipère"},{"a caballo entre","à cheval entre"},{"tener la piel de gallina","avoir la chair de poule"},{"ser la gallina de los huevos de oro","être la poule aux œufs d'or"},{"buscar una aguja en un pajar","chercher une aiguille dans une botte de foin"},{"el gusanillo","le petit creux / le virus (passion)"}}},
{name="Expresiones con comida",t="x",w={{"ser la leche","être incroyable (fam.)"},{"importar un pimiento","s'en ficher"},{"dar las uvas","prendre une éternité"},{"estar como un queso","être canon"},{"ser un melón","être un idiot (fam.)"},{"pedir peras","demander l'impossible"},{"ser del año de la pera","dater de Mathusalem"},{"estar en el ajo","être dans le coup"},{"ponerse como un fideo","maigrir énormément"},{"las cuentas claras y el chocolate espeso","les bons comptes font les bons amis"},{"ganarse el pan","gagner son pain"},{"al pan, pan, y al vino, vino","appeler un chat un chat"},{"ser más bueno que el pan","être bon comme le pain"},{"contigo, pan y cebolla","avec toi, même dans la misère"},{"estar como una rosquilla","être comme un coq en pâte"},{"venderse como churros","se vendre comme des petits pains"},{"mezclar churras con merinas","mélanger les torchons et les serviettes"},{"dar la vuelta a la tortilla","renverser la situation"},{"sacar tajada","tirer profit"},{"estar de mala uva","être de mauvaise humeur"},{"ser un pastel","être un mélange raté"},{"como agua para chocolate","bouillant de colère / de passion"},{"ser la guinda del pastel","être la cerise sur le gâteau"},{"no estar el horno para bollos","ce n'est pas le moment"},{"hacer la pelota","faire de la lèche"},{"estar hecho un flan","être dans tous ses états"},{"me importa un rábano","je m'en moque"},{"ser una patata","être nul (fam.)"},{"tener mala leche","être méchant / mal luné"},{"pedir la luna","demander la lune"}}},
{name="Expresiones con el cuerpo",t="x",w={{"no tener dos dedos de frente","ne pas avoir deux sous de jugeote"},{"ser uña y carne con alguien","être comme les deux doigts de la main"},{"costar un riñón","coûter un rein"},{"poner el grito en el cielo","pousser les hauts cris"},{"echar una mano a alguien","aider quelqu'un"},{"tener mano izquierda","avoir du doigté"},{"estar con el agua al cuello","avoir la corde au cou"},{"tomar el pelo a alguien","se moquer de quelqu'un"},{"morderse la lengua","se mordre la langue"},{"tener buen ojo","avoir l'œil"},{"en un abrir de ojos","en un clin d'œil"},{"hablar por los codos de algo","parler sans arrêt de quelque chose"},{"tener la cabeza dura","avoir la tête dure"},{"meter las narices","fourrer son nez"},{"no tener pelos en la lengua al hablar","ne pas mâcher ses mots en parlant"},{"partirse de risa","se tordre de rire"},{"tener el corazón en un puño","avoir le cœur serré"},{"levantarse con el pie izquierdo","se lever du pied gauche"},{"ser de carne y hueso","être fait de chair et de sang"},{"lavarse las manos","s'en laver les mains"},{"estar hasta el cuello","être débordé"},{"dar la espalda","tourner le dos"},{"echar en cara","reprocher"},{"a pie juntillas","dur comme fer"},{"con los brazos abiertos","à bras ouverts"},{"tener estómago","avoir du cran"},{"no pegar ojo en toda la noche","ne pas fermer l'œil de la nuit"},{"abrir la boca","ouvrir la bouche"},{"ponerse en la piel de otro","se mettre à la place d'un autre"},{"tener la lengua larga","être une langue de vipère"}}},
{name="Refranes 2",t="x",w={{"a mal tiempo, buena cara","bonne figure par mauvais temps"},{"quien siembra vientos recoge tempestades","qui sème le vent récolte la tempête"},{"más vale tarde que nunca, dice el refrán","mieux vaut tard que jamais, dit le proverbe"},{"lo que no mata engorda","ce qui ne tue pas rend plus fort"},{"ande yo caliente, ríase la gente","peu m'importe ce qu'on dit"},{"hablando del rey de Roma","quand on parle du loup"},{"no hay dos sin tres","jamais deux sans trois"},{"donde hubo fuego, cenizas quedan","il reste toujours quelque chose d'un grand amour"},{"a río revuelto, ganancia de pescadores","pêcher en eau trouble"},{"el que avisa no es traidor","un homme averti en vaut deux"},{"la curiosidad mató al gato","la curiosité est un vilain défaut"},{"sobre gustos no hay nada escrito","des goûts et des couleurs on ne discute pas"},{"quien a buen árbol se arrima, buena sombra le cobija","qui a de bons appuis est bien protégé"},{"de tal palo, tal astilla","tel père, tel fils"},{"ojo por ojo, diente por diente","œil pour œil, dent pour dent"},{"en el país de los ciegos, el tuerto es rey","au royaume des aveugles, les borgnes sont rois"},{"el pez grande se come al chico","les gros mangent les petits"},{"más sabe el diablo por viejo que por diablo","l'expérience vaut mieux que le talent"},{"nunca es tarde si la dicha es buena","il n'est jamais trop tard pour bien faire"},{"piensa el ladrón que todos son de su condición","chacun voit les autres à son image"},{"quien busca, encuentra","qui cherche trouve"},{"el que no llora, no mama","qui ne demande rien n'a rien"},{"haz bien y no mires a quién","fais le bien sans regarder à qui"},{"tanto va el cántaro a la fuente que al final se rompe","tant va la cruche à l'eau qu'à la fin elle se casse"},{"después de la tempestad viene la calma","après la pluie vient le beau temps"},{"mal de muchos, consuelo de tontos","le malheur des uns console les sots"},{"no dejes para mañana lo que puedas hacer hoy","ne remets pas à demain ce que tu peux faire aujourd'hui"},{"cuando el río suena, agua lleva","il n'y a pas de fumée sans feu"},{"el que mucho habla, mucho yerra","qui parle beaucoup se trompe beaucoup"},{"quien bien te quiere te hará llorar","qui aime bien châtie bien"}}},
